<script setup lang="ts">
type Profile = { gender: string; age: number | null; height: number | null; heightUnit: string; weight: number | null; weightUnit: string; activityLevel: string; goal: string; dietaryPreference: string; allergies: string; foodsToAvoid: string; mealsPerDay: number }
type Meal = { id?: string; mealType: string; mealName?: string; name?: string; description: string; ingredients: string[]; servingSize: string; calories: number; protein: number; carbohydrates: number; fat: number; suggestedTime: string; completed?: boolean }
type Day = { id?: string; dayNumber: number; date: string; meals: Meal[]; summary: { calories: number; protein: number; carbohydrates: number; fat: number } }
const { data, refresh } = await useFetch<any>('/api/diet-plan')
const defaults: Profile = { gender: '', age: null, height: null, heightUnit: 'cm', weight: null, weightUnit: 'kg', activityLevel: '', goal: '', dietaryPreference: 'no_preference', allergies: '', foodsToAvoid: '', mealsPerDay: 5 }
const form = reactive<Profile>({ ...defaults })
const preview = ref<any>(null), activeDay = ref(0), loading = ref(false), saving = ref(false), error = ref(''), notice = ref(''), editing = ref(true)
watch(() => data.value?.profile, p => { if (p) { Object.assign(form, p, { height: Number(p.height), weight: Number(p.weight) }); editing.value = !data.value?.plan } }, { immediate: true })
const savedPlan = computed(() => data.value?.plan || null)
const days = computed<Day[]>(() => preview.value?.days || savedPlan.value?.days || [])
const currentDay = computed(() => days.value[activeDay.value])
const activePlan = computed(() => Boolean(savedPlan.value))
const today = new Date().toLocaleDateString('en-CA')
const todayDay = computed(() => days.value.find(day => day.date === today))
const todayCompleted = computed(() => todayDay.value?.meals.filter(meal => meal.completed).length || 0)
const todayAdherence = computed(() => data.value?.adherence?.find((row: any) => row.date === today)?.followed)
const weekly = computed(() => data.value?.weekly || { followedDays: 0, totalDays: 0, completedMeals: 0, totalMeals: 0, currentStreak: 0 })
const label = (value: string) => ({ lose_weight: 'Lose weight', maintain_weight: 'Maintain weight', gain_weight: 'Gain weight', no_preference: 'No specific preference', prefer_not_to_say: 'Prefer not to say', sedentary: 'Sedentary', lightly_active: 'Lightly active', moderately_active: 'Moderately active', very_active: 'Very active', extremely_active: 'Extremely active', male: 'Male', female: 'Female', vegetarian: 'Vegetarian', vegan: 'Vegan', high_protein: 'High protein', low_carb: 'Low carb', other: 'Other' }[value] || value)
const profileValid = computed(() => Boolean(
  form.gender && Number.isFinite(Number(form.age)) && Number(form.age) >= 18 && Number(form.age) <= 100 &&
  Number.isFinite(Number(form.height)) && Number(form.height) > 0 &&
  Number.isFinite(Number(form.weight)) && Number(form.weight) > 0 &&
  form.activityLevel && form.goal
))
const missingProfileFields = () => {
  const missing: string[] = []
  if (!form.gender) missing.push('gender')
  if (!form.age || form.age < 18 || form.age > 100) missing.push('a valid age (18–100)')
  if (!form.height || form.height <= 0) missing.push('height')
  if (!form.weight || form.weight <= 0) missing.push('weight')
  if (!form.activityLevel) missing.push('activity level')
  if (!form.goal) missing.push('goal')
  return missing
}
const saveFailure = (e: any) => { error.value = e?.data?.statusMessage || e?.message || 'Something went wrong. Please try again.' }
async function generate() {
  const missing = missingProfileFields()
  if (missing.length) { error.value = `Please complete ${missing.join(', ')} to generate your plan.`; return }
  loading.value = true; error.value = ''; notice.value = ''
  try { preview.value = await $fetch<any>('/api/diet-plan/generate', { method: 'POST', body: { ...form } }); activeDay.value = 0; editing.value = false }
  catch (e) { saveFailure(e) } finally { loading.value = false }
}
async function savePlan() {
  if (!preview.value) return
  saving.value = true; error.value = ''; notice.value = ''
  try { await $fetch('/api/diet-plan/save', { method: 'POST', body: { requestKey: preview.value.requestKey, startDate: new Date().toLocaleDateString('en-CA'), profile: { ...form } } }); preview.value = null; await refresh(); activeDay.value = 0; editing.value = false; notice.value = 'Your diet plan has been saved.' }
  catch (e) { saveFailure(e) } finally { saving.value = false }
}
async function toggleMeal(meal: Meal) {
  if (!meal.id) return
  error.value = ''
  try { await $fetch(`/api/diet-plan/meals/${meal.id}`, { method: 'PUT', body: { completed: !meal.completed } }); await refresh() } catch (e) { saveFailure(e) }
}
async function toggleFollowed() {
  if (!currentDay.value || !activePlan.value) return
  try { await $fetch('/api/diet-plan/adherence', { method: 'PUT', body: { date: currentDay.value.date, followed: data.value?.adherence?.find((row: any) => row.date === currentDay.value.date)?.followed !== true } }); await refresh() } catch (e) { saveFailure(e) }
}
function editProfile() { editing.value = true; nextTick(() => document.getElementById('diet-profile-form')?.scrollIntoView({ behavior: 'smooth', block: 'start' })) }
const dateLabel = (iso: string) => new Date(`${iso}T00:00:00`).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })
const daysShort = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
</script>

<template>
  <div class="diet-page">
    <header class="diet-header">
      <div><p class="diet-eyebrow">DIET PLAN</p><h1>Your Personalized Diet Plan</h1><p class="diet-subtitle">Create a meal plan based on your body details, goals, activity level, and food preferences.</p></div>
      <div class="diet-header-art" aria-hidden="true"><span>Better food<br>for a healthier you</span><i>✦</i><i>❋</i></div>
    </header>
    <p v-if="error" class="diet-alert" role="alert">{{ error }}</p>
    <p v-if="notice" class="diet-notice" role="status">{{ notice }}</p>
    <div class="diet-layout">
      <main class="diet-main-column">
        <section id="diet-profile-form" class="diet-card diet-form-card">
          <div class="diet-section-heading"><span class="diet-step">1</span><div><h2>Tell us about yourself</h2><p>Your details help us create a more personalized plan.</p></div></div>
          <form @submit.prevent="generate">
            <div class="diet-form-grid">
              <fieldset class="diet-field diet-gender-field"><legend>Gender</legend><div class="diet-choice-row"><label v-for="option in [['male','Male'],['female','Female'],['prefer_not_to_say','Prefer not to say']]" :key="option[0]" class="diet-choice" :class="form.gender === option[0] ? 'selected' : ''"><input v-model="form.gender" type="radio" name="gender" :value="option[0]" required><span class="diet-radio"></span>{{ option[1] }}</label></div></fieldset>
              <label class="diet-field"><span>Age</span><div class="diet-input-wrap"><input v-model.number="form.age" type="number" min="18" max="100" placeholder="28" required><span>years</span></div></label>
              <label class="diet-field"><span>Height</span><div class="diet-input-wrap"><input v-model.number="form.height" type="number" min="1" :max="form.heightUnit === 'cm' ? 250 : 96" placeholder="170" required><select v-model="form.heightUnit"><option value="cm">cm</option><option value="ft_in">in</option></select></div></label>
              <label class="diet-field"><span>Weight</span><div class="diet-input-wrap"><input v-model.number="form.weight" type="number" min="1" :max="form.weightUnit === 'kg' ? 400 : 880" placeholder="65" required><select v-model="form.weightUnit"><option value="kg">kg</option><option value="lb">lb</option></select></div></label>
              <label class="diet-field diet-wide-field"><span>Activity level</span><select v-model="form.activityLevel" required><option disabled value="">Choose activity level</option><option value="sedentary">Sedentary</option><option value="lightly_active">Lightly active</option><option value="moderately_active">Moderately active</option><option value="very_active">Very active</option><option value="extremely_active">Extremely active</option></select></label>
              <fieldset class="diet-field diet-goal-field"><legend>Your goal</legend><div class="diet-goal-row"><label v-for="option in [['lose_weight','↘','Lose weight'],['maintain_weight','↔','Maintain weight'],['gain_weight','↗','Gain weight']]" :key="option[0]" class="diet-goal-option" :class="form.goal === option[0] ? 'selected' : ''"><input v-model="form.goal" type="radio" name="goal" :value="option[0]" required><span>{{ option[1] }}</span>{{ option[2] }}</label></div></fieldset>
              <label class="diet-field"><span>Dietary preference</span><select v-model="form.dietaryPreference"><option value="no_preference">No specific preference</option><option value="vegetarian">Vegetarian</option><option value="vegan">Vegan</option><option value="high_protein">High protein</option><option value="low_carb">Low carb</option><option value="other">Other</option></select></label>
              <label class="diet-field"><span>Meals per day</span><select v-model.number="form.mealsPerDay"><option :value="3">3 meals</option><option :value="4">4 meals</option><option :value="5">5 meals</option></select></label>
              <label class="diet-field"><span>Food allergies <small>(optional)</small></span><input v-model="form.allergies" type="text" placeholder="e.g. nuts, dairy, shellfish" maxlength="500"></label>
              <label class="diet-field"><span>Foods to avoid <small>(optional)</small></span><input v-model="form.foodsToAvoid" type="text" placeholder="e.g. sugar, processed foods" maxlength="500"></label>
            </div>
            <div class="diet-form-footer"><p>Estimates are for general wellness planning and are not medical advice.</p><button class="diet-button" type="submit" :disabled="!profileValid || loading">{{ loading ? 'Generating…' : 'Generate diet plan' }} <span>✦</span></button></div>
          </form>
        </section>

        <section v-if="days.length" class="diet-card diet-plan-card">
          <div class="diet-section-heading diet-plan-heading"><span class="diet-step">2</span><div><h2>Your 7-Day Diet Plan</h2><p>A balanced and realistic plan tailored to your goals and preferences.</p></div><button v-if="preview" class="diet-outline-button" @click="savePlan" :disabled="saving">{{ saving ? 'Saving…' : 'Save this plan' }}</button><button v-else class="diet-outline-button" @click="editProfile">Edit profile</button></div>
          <div class="diet-day-tabs"><button v-for="(day, index) in days" :key="day.date" :class="activeDay === index ? 'active' : ''" @click="activeDay = index"><strong>Day {{ day.dayNumber }}</strong><span>{{ daysShort[index] }} · {{ dateLabel(day.date) }}</span></button></div>
          <template v-if="currentDay">
            <div class="diet-day-summary"><div><h3>Day {{ currentDay.dayNumber }} – {{ new Date(`${currentDay.date}T00:00:00`).toLocaleDateString(undefined, { weekday: 'long' }) }}</h3><p>{{ dateLabel(currentDay.date) }} · {{ label(form.goal) || label(savedPlan?.goal || '') }}</p></div><div class="diet-metrics"><div><b>{{ currentDay.summary.calories.toLocaleString() }}</b><span>Calories</span></div><div><b>{{ currentDay.summary.protein }}g</b><span>Protein</span></div><div><b>{{ currentDay.summary.carbohydrates }}g</b><span>Carbs</span></div><div><b>{{ currentDay.summary.fat }}g</b><span>Fat</span></div></div></div>
            <div class="diet-meal-list"><article v-for="meal in currentDay.meals" :key="meal.id || `${currentDay.date}-${meal.mealType}`" class="diet-meal-row"><span class="diet-meal-type">{{ meal.mealType }}</span><div class="diet-meal-copy"><div class="diet-meal-top"><strong>{{ meal.mealName || meal.name }}</strong><span>◷ {{ meal.suggestedTime }}</span></div><p>{{ meal.description }}</p><small>{{ meal.ingredients.join(' · ') }} · {{ meal.servingSize }}</small></div><div class="diet-meal-nutrition"><span><b>{{ meal.calories }}</b> kcal</span><span><b>{{ meal.protein }}g</b> protein</span><span><b>{{ meal.carbohydrates }}g</b> carbs</span><span><b>{{ meal.fat }}g</b> fat</span></div><button v-if="activePlan" class="diet-complete" :class="meal.completed ? 'done' : ''" @click="toggleMeal(meal)">{{ meal.completed ? '✓ Completed' : 'Mark complete' }}</button></article></div>
            <div v-if="activePlan" class="diet-follow-row"><span>{{ currentDay.meals.filter(meal => meal.completed).length }} / {{ currentDay.meals.length }} meals completed</span><button class="diet-outline-button" @click="toggleFollowed">{{ data?.adherence?.find((row: any) => row.date === currentDay.date)?.followed === true ? '✓ Plan followed' : 'Mark day followed' }}</button></div>
          </template>
          <p class="diet-disclaimer">Nutrition values are estimates. Review serving sizes and check ingredient labels, especially for allergies.</p>
        </section>
        <section v-else class="diet-empty-plan"><span>✦</span><h2>Your plan will appear here</h2><p>Complete your profile above to get a personalized 7-day meal plan.</p></section>
      </main>

      <aside class="diet-side-column">
        <section class="diet-card diet-profile-summary"><div class="diet-side-title"><h2>Your Profile</h2><button @click="editProfile">✎ Edit</button></div><div v-if="form.age" class="diet-profile-grid"><div><span class="diet-summary-icon mint">▦</span><p><small>Age</small><b>{{ form.age }} years</b></p></div><div><span class="diet-summary-icon blue">◉</span><p><small>Gender</small><b>{{ label(form.gender) }}</b></p></div><div><span class="diet-summary-icon mint">↕</span><p><small>Height</small><b>{{ form.height }} {{ form.heightUnit === 'cm' ? 'cm' : 'in' }}</b></p></div><div><span class="diet-summary-icon purple">▣</span><p><small>Weight</small><b>{{ form.weight }} {{ form.weightUnit }}</b></p></div><div><span class="diet-summary-icon orange">♨</span><p><small>Goal</small><b>{{ label(form.goal) }}</b></p></div><div><span class="diet-summary-icon mint">↗</span><p><small>Activity level</small><b>{{ label(form.activityLevel) }}</b></p></div><div class="diet-profile-wide"><span class="diet-summary-icon mint">❧</span><p><small>Dietary preference</small><b>{{ label(form.dietaryPreference) }}</b></p></div></div><div v-else class="diet-side-empty">Add your details to see your profile summary.</div></section>
        <section class="diet-card diet-today-card"><div class="diet-side-title"><div><h2>Today's Progress</h2><small>{{ todayDay ? dateLabel(todayDay.date) : 'No plan for today' }}</small></div><span v-if="todayDay" class="diet-progress-ring"><b>{{ todayCompleted }}<small>/{{ todayDay.meals.length }}</small></b></span></div><div v-if="todayDay" class="diet-today-content"><div><p>{{ todayCompleted }} of {{ todayDay.meals.length }} meals completed</p><div v-for="meal in todayDay.meals" :key="meal.id" class="diet-today-meal"><span :class="meal.completed ? 'complete' : ''">{{ meal.completed ? '✓' : '○' }}</span>{{ meal.mealType }}</div></div></div><div v-else class="diet-side-empty">Generate a plan to start tracking today's meals.</div><p v-if="todayDay" class="diet-follow-state">{{ todayAdherence === true ? '✓ You marked today as followed' : todayAdherence === false ? 'Today marked as not followed' : 'Mark each meal as you complete it' }}</p></section>
        <section class="diet-card diet-weekly-card"><div class="diet-side-title"><div><h2>Weekly Progress</h2><small>From your saved plan activity</small></div></div><div class="diet-weekly-stats"><div><span class="mint">▦</span><b>{{ weekly.followedDays }} / {{ weekly.totalDays }}</b><small>Days followed</small></div><div><span class="blue">☷</span><b>{{ weekly.completedMeals }} / {{ weekly.totalMeals }}</b><small>Meals completed</small></div><div><span class="orange">♨</span><b>{{ weekly.currentStreak }}</b><small>Day streak</small></div></div><div v-if="days.length" class="diet-weekly-list"><div v-for="(day, index) in days" :key="day.date"><b>{{ daysShort[index] }}</b><span>{{ dateLabel(day.date) }}</span><i :class="data?.adherence?.find((row: any) => row.date === day.date)?.followed === true ? 'followed' : ''">{{ data?.adherence?.find((row: any) => row.date === day.date)?.followed === true ? '✓' : '○' }}</i><small>{{ data?.adherence?.find((row: any) => row.date === day.date)?.followed === true ? 'Plan followed' : data?.adherence?.find((row: any) => row.date === day.date)?.followed === false ? 'Not followed' : 'Not marked' }}</small></div></div><p v-else class="diet-side-empty">Progress appears here as you log meals and confirm days.</p></section>
      </aside>
    </div>
  </div>
</template>

<style scoped>
